package com.vidacruz.triage.infrastructure.persistence;

import com.vidacruz.triage.application.port.PatientRepository;
import com.vidacruz.triage.domain.Patient;
import com.vidacruz.triage.domain.VitalSigns;
import org.springframework.r2dbc.core.DatabaseClient;
import org.springframework.stereotype.Repository;
import reactor.core.publisher.Mono;

/**
 * Patients over R2DBC with explicit SQL: the id is generated by the application, so a plain INSERT avoids the
 * insert-vs-update guessing of Spring Data repositories.
 */
@Repository
class R2dbcPatientRepository implements PatientRepository {

	private final DatabaseClient db;

	R2dbcPatientRepository(DatabaseClient db) {
		this.db = db;
	}

	@Override
	public Mono<Void> insert(Patient patient) {
		VitalSigns v = patient.vitalSigns();
		return db.sql("""
				INSERT INTO patients (id, full_name, age, heart_rate, systolic_bp, diastolic_bp, spo2, temperature,
				                      pain_level, gcs, chief_complaint, level, sla_minutes, status, escalated,
				                      registered_at, status_changed_at)
				VALUES (:id, :fullName, :age, :heartRate, :systolic, :diastolic, :spo2, :temperature,
				        :pain, :gcs, :chiefComplaint, :level, :slaMinutes, :status, :escalated,
				        :registeredAt, :statusChangedAt)
				""")
			.bind("id", patient.id())
			.bind("fullName", patient.fullName())
			.bind("age", patient.age())
			.bind("heartRate", v.heartRate())
			.bind("systolic", v.systolicPressure())
			.bind("diastolic", v.diastolicPressure())
			.bind("spo2", v.oxygenSaturation())
			.bind("temperature", v.temperature())
			.bind("pain", v.painLevel())
			.bind("gcs", v.glasgowScale())
			.bind("chiefComplaint", patient.chiefComplaint())
			.bind("level", patient.level().name())
			.bind("slaMinutes", patient.slaMinutes())
			.bind("status", patient.status().name())
			.bind("escalated", patient.escalated())
			.bind("registeredAt", patient.registeredAt())
			.bind("statusChangedAt", patient.statusChangedAt())
			.then();
	}

}
